import{_ as t}from"./chunks/image.1TJKpa6R.js";import{_ as a,o as n,c as r,a2 as i}from"./chunks/framework.CdjpmwdR.js";const w=JSON.parse('{"title":"Tunnel, VPN, VPC: Boundaries and Relationships","description":"Clarifies Tunnel, VPN, and VPC from a networking perspective, focusing on their roles in connectivity, security, and virtual network abstraction.","frontmatter":{"category":"node","date":"2023-04-01","title":"Tunnel, VPN, VPC: Boundaries and Relationships","description":"Clarifies Tunnel, VPN, and VPC from a networking perspective, focusing on their roles in connectivity, security, and virtual network abstraction.","tags":["node","networking","K8s"],"image":"/blogs/assets/202304-tunnel-vpn-vpc/image.png"},"headers":[],"relativePath":"en/blogs/2023/202304-tunnel-vpn-vpc.md","filePath":"en/blogs/2023/202304-tunnel-vpn-vpc.md"}'),o={name:"en/blogs/2023/202304-tunnel-vpn-vpc.md"};function l(s,e,c,u,p,d){return n(),r("div",null,[...e[0]||(e[0]=[i('<p>This started as a note I wrote while sorting out VPN-related concepts.</p><blockquote><p>A sequel to <a href="./../2022/202205-router-proxy-gtw">Router vs Proxy vs Gateway</a></p></blockquote><h2 id="tunnel-–-connecting-two-unreachable-networks" tabindex="-1">Tunnel – Connecting Two Unreachable Networks <a class="header-anchor" href="#tunnel-–-connecting-two-unreachable-networks" aria-label="Permalink to &quot;Tunnel – Connecting Two Unreachable Networks&quot;">​</a></h2><p><img src="https://s2.loli.net/2023/04/17/y5EnxTrbtIAN7z9.png" alt="tunnel"></p><p>Routers and proxies mainly <strong>forward</strong> traffic. Tunnels emphasize <strong>encapsulate, then transmit</strong>.</p><p>Typical use cases:</p><ul><li>Connect two networks that cannot reach each other directly (often across the public Internet)</li><li>Bridge different protocol domains</li></ul><p>A tunnel usually:</p><ul><li>Wraps or rewrites the original packet header</li><li>Encrypts the payload</li><li>Adds extra metadata (logging, tracing, etc.)</li></ul><p>Every layer of the network stack is itself &quot;wrapping&quot; packets, so in theory you can create a tunnel on <strong>any layer</strong> as long as you can encode/decode packets at that layer.</p><h2 id="vpn-–-virtual-private-network" tabindex="-1">VPN – Virtual Private Network <a class="header-anchor" href="#vpn-–-virtual-private-network" aria-label="Permalink to &quot;VPN – Virtual Private Network&quot;">​</a></h2><p><img src="https://s2.loli.net/2023/04/17/KMUOH1bTycPYtJv.png" alt="vpn"></p><p>A VPN always has two ends: <strong>Server</strong> and <strong>Client</strong>. The client must connect to the server to work.</p><ul><li>The server acts as a <strong>gateway</strong> to other networks for clients</li><li>The link between server and client is typically built on top of <strong>tunnels</strong>, to secure cross‑network traffic</li></ul><p>So from a networking perspective, a VPN is a set of tunnels with a control plane and addressing model on top.</p><h2 id="tun-tap-–-virtual-network-devices" tabindex="-1">TUN/TAP – Virtual Network Devices <a class="header-anchor" href="#tun-tap-–-virtual-network-devices" aria-label="Permalink to &quot;TUN/TAP – Virtual Network Devices&quot;">​</a></h2><p>TUN/TAP are Linux virtual network devices that allow a single host to have additional virtual IP/MAC identities.</p><p>They are often used together with VPNs and tunnels to:</p><ul><li>Give processes or containers their own network stack</li><li>Inject or capture packets in user space</li></ul><h2 id="underlay-vs-overlay" tabindex="-1">Underlay vs Overlay <a class="header-anchor" href="#underlay-vs-overlay" aria-label="Permalink to &quot;Underlay vs Overlay&quot;">​</a></h2><p>Because of tunnels and virtual devices, <strong>logical</strong> topology and <strong>physical</strong> topology can look completely different:</p><ul><li>Two machines on different continents can appear to be on the <strong>same LAN and subnet</strong></li><li>Two applications on the <strong>same host</strong> can be placed into different virtual networks and isolated from each other</li></ul><p>This is exactly the idea of <strong>overlay networks</strong> built on top of a physical <strong>underlay</strong>.</p><h2 id="vpc-vnet-–-virtual-private-cloud" tabindex="-1">VPC / VNet – Virtual Private Cloud <a class="header-anchor" href="#vpc-vnet-–-virtual-private-cloud" aria-label="Permalink to &quot;VPC / VNet – Virtual Private Cloud&quot;">​</a></h2><p>As we add more and more virtual devices and endpoints, VPNs start dealing with:</p><ul><li>Many nodes</li><li>Multicast / broadcast</li><li>VM‑to‑VM communication on the same host</li></ul><p>At data‑center scale this leads to <strong>virtual LAN / data center networking</strong> technologies, and cloud vendors built their own abstractions: VPC (AWS/GCP/AliCloud), VNet (Azure), etc.</p><p>Conceptually a VPC/VNet is:</p><ul><li>A virtual L3 network with its own CIDR blocks</li><li>A boundary for routing, security groups and peering</li><li>Often implemented using a mix of tunnels, encapsulation (VXLAN/Geneve), and virtual routers</li></ul><h2 id="virtual-networks-vs-container-networking" tabindex="-1">Virtual Networks vs Container Networking <a class="header-anchor" href="#virtual-networks-vs-container-networking" aria-label="Permalink to &quot;Virtual Networks vs Container Networking&quot;">​</a></h2><p>These two worlds are very similar:</p><ul><li>Both build overlays on top of physical networks</li><li>Both use encapsulation and virtual interfaces to isolate tenants / workloads</li><li>Both rely on routing rules and policies to control reachability</li></ul><p>The main difference is focus:</p><ul><li>VPC/VNet: cloud accounts, subnets, security groups</li><li>Container networking: Pods, Services, CNI plugins</li></ul><h2 id="appendix-landscape" tabindex="-1">Appendix: Landscape <a class="header-anchor" href="#appendix-landscape" aria-label="Permalink to &quot;Appendix: Landscape&quot;">​</a></h2><p><img src="'+t+'" alt="landscape"></p><h3 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h3><ul><li><a href="https://support.huawei.com/enterprise/zh/doc/EDOC1100164807" target="_blank" rel="noreferrer">https://support.huawei.com/enterprise/zh/doc/EDOC1100164807</a></li><li><a href="https://itnext.io/kubernetes-is-hard-why-eks-makes-it-easier-for-network-and-security-architects-ea6d8b2ca965" target="_blank" rel="noreferrer">https://itnext.io/kubernetes-is-hard-why-eks-makes-it-easier-for-network-and-security-architects-ea6d8b2ca965</a></li><li><a href="https://www.pinterest.com/pin/coreosflannel--22940279328297785/" target="_blank" rel="noreferrer">https://www.pinterest.com/pin/coreosflannel--22940279328297785/</a></li><li><a href="https://access.redhat.com/documentation/en-us/red_hat_virtualization/4.4/html/technical_reference/cluster_networking" target="_blank" rel="noreferrer">https://access.redhat.com/documentation/en-us/red_hat_virtualization/4.4/html/technical_reference/cluster_networking</a></li><li><a href="https://www.rebeladmin.com/2018/01/azure-accelerated-networking/" target="_blank" rel="noreferrer">https://www.rebeladmin.com/2018/01/azure-accelerated-networking/</a></li><li><a href="https://dzone.com/articles/step-by-step-guide-establishing-container-networki" target="_blank" rel="noreferrer">https://dzone.com/articles/step-by-step-guide-establishing-container-networki</a></li><li><a href="https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/6/html/virtualization_administration_guide/sect-attch-nic-physdev" target="_blank" rel="noreferrer">https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/6/html/virtualization_administration_guide/sect-attch-nic-physdev</a></li><li><a href="https://zh.wikipedia.org/zh-cn/%E9%9A%A7%E9%81%93%E5%8D%8F%E8%AE%AE" target="_blank" rel="noreferrer">https://zh.wikipedia.org/zh-cn/隧道协议</a></li></ul>',38)])])}const v=a(o,[["render",l]]);export{w as __pageData,v as default};
